145: function playTone(frequency, duration) {
146:   if (!soundOn) return;
147:   try {
148:     audioContext ||= new (window.AudioContext || window.webkitAudioContext)();
149:     const oscillator = audioContext.createOscillator();
150:     const gain = audioContext.createGain();
151:     oscillator.type = 'sine'; oscillator.frequency.value = frequency;
152:     gain.gain.setValueAtTime(.035, audioContext.currentTime);
153:     gain.gain.exponentialRampToValueAtTime(.001, audioContext.currentTime + duration);
154:     oscillator.connect(gain); gain.connect(audioContext.destination);
155:     oscillator.start(); oscillator.stop(audioContext.currentTime + duration);
156:   } catch (_) { /* Audio is an optional flourish. */ }
157: }
